(function(){
  const MSG_REQUIRED='Por favor, completa este campo.';
  const MSG_INVALID='Introduce una respuesta válida.';

  function groupOf(el){ return el.closest('.elementor-field-group')||el.parentElement; }
  function removeError(el){
    const g=groupOf(el); if(!g) return;
    g.classList.remove('evc-has-error');
    const old=g.querySelector('.evc-error'); if(old) old.remove();
  }
  function after(ref,node){ ref.parentNode.insertBefore(node,ref.nextSibling); }
  function showError(el,msg){
    const g=groupOf(el); if(!g) return;
    removeError(el);
    const err=document.createElement('div');
    err.className='evc-error';
    err.textContent=msg;
    const wrap=g.querySelector('.elementor-select-wrapper');
    const subgroup=g.querySelector('.elementor-field-subgroup');
    if(wrap && (wrap.contains(el) || el.tagName==='SELECT')) after(wrap,err);
    else if(subgroup && subgroup.contains(el)) after(subgroup,err);
    else after(el,err);
    g.classList.add('evc-has-error');
  }

  // Nossas regras custom
  function validateSelectPlaceholder(el){
    if(el.tagName!=='SELECT') return;
    const val=(el.value||'').trim();
    if(val===''||val==='Selecciona') el.setCustomValidity(MSG_REQUIRED);
    else el.setCustomValidity('');
  }
  function validateFileSize(el){
    if(el.type!=='file') return;
    const maxMb=el.getAttribute('data-maxsize');
    if(!maxMb||!el.files||!el.files[0]){ el.setCustomValidity(''); return; }
    const maxBytes=parseFloat(maxMb)*1024*1024;
    const tooBig=[...el.files].some(f=>f.size>maxBytes);
    el.setCustomValidity(tooBig?`El archivo supera el tamaño máximo permitido (${maxMb} MB).`:'' );
  }

  // NUNCA usamos el.validationMessage (que vem em inglês). Só nossas strings:
  function messageFor(el){
    const v=el.validity;
    if(v.valueMissing) return MSG_REQUIRED;
    if(v.typeMismatch||v.patternMismatch||v.badInput||v.stepMismatch||v.rangeOverflow||v.rangeUnderflow) return MSG_INVALID;
    return '';
  }

  function validate(el){
    // limpar qualquer mensagem anterior para recalcular do zero
    el.setCustomValidity('');
    // aplicar regras custom
    validateSelectPlaceholder(el);
    validateFileSize(el);

    // perguntar ao motor se está válido (sem usar o texto dele)
    if(!el.checkValidity()){
      const msg = messageFor(el) || MSG_INVALID;  // <-- só nossas mensagens
      el.setCustomValidity(msg);                  // força espanhol
      showError(el, msg);
      return false;
    } else {
      removeError(el);
      return true;
    }
  }

  const forms=[...document.querySelectorAll('form.elementor-form')];
  if(!forms.length) return;

  forms.forEach(form=>{
    // 1) desativa UI nativa
    form.setAttribute('novalidate','');

    // 2) remove possíveis "titles" que alguns navegadores exibem
    form.querySelectorAll('[title]').forEach(el=>el.removeAttribute('title'));

    // 3) suprime tooltip nativo (captura)
    form.addEventListener('invalid', function(e){
      e.preventDefault();
    }, true);

    // 4) Neutraliza reportValidity() que possa ser chamado por scripts
    // Executa nossa validação e retorna boolean, sem tooltips do browser
    const nativeReport = form.reportValidity?.bind(form);
    form.reportValidity = function(){
      const controls=[...form.querySelectorAll('input, select, textarea')];
      let ok=true;
      controls.forEach(el=>{
        if(el.disabled) return;
        const grp=groupOf(el);
        if(grp && getComputedStyle(grp).display==='none') return; // condicionais ocultos
        if(!validate(el)) ok=false;
      });
      return ok;
    };

    const controls=[...form.querySelectorAll('input, select, textarea')];

    // listeners por campo
    controls.forEach(el=>{
      const evt=(el.tagName==='SELECT'||['checkbox','radio','file'].includes(el.type))?'change':'input';
      el.addEventListener(evt,()=>validate(el));
      el.addEventListener('blur',()=>validate(el));
    });

    // submit handler
    form.addEventListener('submit',e=>{
      let ok=true;
      controls.forEach(el=>{
        if(el.disabled) return;
        const grp=groupOf(el);
        if(grp && getComputedStyle(grp).display==='none') return;
        if(!validate(el)) ok=false;
      });
      if(!ok){
        e.preventDefault();
        const first=form.querySelector('.evc-has-error .elementor-field, .evc-has-error select, .evc-has-error input, .evc-has-error textarea');
        if(first) first.focus({preventScroll:false});
      }
    });
  });
})();